 22	package br.com.marealta.pousada;
 23	
 24	import br.com.marealta.pousada.Domain.ApiException;
 25	import br.com.marealta.pousada.Domain.RatePlan;
 26	import com.fasterxml.jackson.databind.DeserializationFeature;
 27	import com.fasterxml.jackson.databind.JsonNode;
 28	import com.fasterxml.jackson.databind.ObjectMapper;
 29	import com.fasterxml.jackson.databind.SerializationFeature;
 30	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
 31	import io.javalin.Javalin;
 32	import io.javalin.http.Context;
 33	import io.javalin.json.JavalinJackson;
 34	
 35	import java.time.LocalDate;
 36	import java.time.YearMonth;
 37	import java.util.Map;
 38	import java.util.regex.Pattern;
 39	
 40	public class Api {
 41	    private static final Pattern DATE = Pattern.compile("\\d{4}-\\d{2}-\\d{2}");
 42	    private static final Pattern MONTH = Pattern.compile("\\d{4}-\\d{2}");
 43	    private static final String CSV = "text/csv; charset=utf-8";
 44	
 45	    private final ReservationService service;
 46	    private final ObjectMapper mapper = new ObjectMapper()
 47	            .registerModule(new JavaTimeModule())
 48	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
 49	            .disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);
 50	
 51	    public Api(ReservationService service) {
 52	        this.service = service;
 53	    }
 54	
 55	    public Javalin build() {
 56	        Javalin app = Javalin.create(cfg -> {
 57	            cfg.showJavalinBanner = false;
 58	            cfg.jsonMapper(new JavalinJackson(mapper, false));
 59	        });
 60	        app.exception(ApiException.class, (e, ctx) ->
 61	                ctx.status(e.status).json(Map.of("error", e.code, "message", e.getMessage())));
 62	        app.exception(Exception.class, (e, ctx) -> {
 63	            e.printStackTrace();
 64	            ctx.status(500).json(Map.of("error", "INTERNAL_ERROR", "message", "Erro interno"));
 65	        });
 66	
 67	        app.get("/rooms", ctx -> ctx.json(service.rooms()));
 68	        app.post("/reservations", ctx -> ctx.status(201).json(service.create(parse(ctx))));
 69	        app.get("/reservations/{id}", ctx -> ctx.json(service.get(id(ctx))));
 70	        app.post("/reservations/{id}/confirmation", ctx -> ctx.json(service.confirm(id(ctx))));
 71	        app.post("/reservations/{id}/cancellation", ctx -> ctx.json(service.cancel(id(ctx))));
 72	        app.post("/reservations/{id}/check-in", ctx -> ctx.json(service.checkIn(id(ctx))));
 73	        app.post("/reservations/{id}/check-out", ctx -> ctx.json(service.checkOut(id(ctx))));
 74	        app.get("/reservations/{id}/document", ctx -> ctx.json(service.document(id(ctx))));
 75	        app.get("/messages", ctx -> ctx.json(service.messages()));
 76	        app.get("/reports/occupancy", ctx -> {
 77	            String raw = ctx.queryParam("date");
 78	            if (raw == null || !DATE.matcher(raw).matches()) throw invalid("Parâmetro date inválido (use AAAA-MM-DD)");
 79	            ctx.contentType(CSV).result(service.occupancyReport(date(raw, "date")));
 80	        });
 81	        app.get("/reports/revenue", ctx -> {
 82	            String raw = ctx.queryParam("month");
 83	            if (raw == null || !MONTH.matcher(raw).matches()) throw invalid("Parâmetro month inválido (use AAAA-MM)");
 84	            YearMonth m;
 85	            try {
 86	                m = YearMonth.parse(raw);
 87	            } catch (RuntimeException e) {
 88	                throw invalid("Parâmetro month inválido (use AAAA-MM)");
 89	            }
 90	            ctx.contentType(CSV).result(service.revenueReport(m));
 91	        });
 92	        return app;
 93	    }
 94	
 95	    private static ApiException invalid(String msg) {
 96	        return new ApiException(400, "INVALID_REQUEST", msg);
 97	    }
 98	
 99	    private static long id(Context ctx) {
100	        try {
101	            return Long.parseLong(ctx.pathParam("id"));
102	        } catch (NumberFormatException e) {
103	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva não encontrada");
104	        }
105	    }
106	
107	    private static LocalDate date(String raw, String field) {
108	        if (raw == null || !DATE.matcher(raw).matches()) throw invalid("Campo " + field + " inválido (use AAAA-MM-DD)");
109	        try {
110	            return LocalDate.parse(raw);
111	        } catch (RuntimeException e) {
112	            throw invalid("Campo " + field + " inválido (use AAAA-MM-DD)");
113	        }
114	    }
115	
116	    private ReservationService.NewReservation parse(Context ctx) {
117	        JsonNode root;
118	        try {
119	            root = mapper.readTree(ctx.body());
120	        } catch (Exception e) {
121	            throw invalid("Corpo da requisição não é um JSON válido");
122	        }
123	        if (root == null || !root.isObject()) throw invalid("Corpo da requisição deve ser um objeto JSON");
124	
125	        int room = integer(root, "roomNumber");
126	        String name = text(root, "guestName");
127	        String email = text(root, "guestEmail");
128	        String cpf = text(root, "guestCpf");
129	        LocalDate in = date(text(root, "checkIn"), "checkIn");
130	        LocalDate out = date(text(root, "checkOut"), "checkOut");
131	        int guests = integer(root, "guests");
132	        RatePlan plan;
133	        try {
134	            plan = RatePlan.valueOf(text(root, "ratePlan"));
135	        } catch (IllegalArgumentException e) {
136	            throw invalid("Campo ratePlan inválido (STANDARD ou NON_REFUNDABLE)");
137	        }
138	        if (!out.isAfter(in)) throw invalid("A saída deve ser depois da entrada");
139	        if (guests < 1) throw invalid("É preciso pelo menos um hóspede");
140	        return new ReservationService.NewReservation(room, name, email, cpf, in, out, guests, plan);
141	    }
142	
143	    private static String text(JsonNode root, String field) {
144	        JsonNode n = root.get(field);
145	        if (n == null || !n.isTextual() || n.asText().isBlank()) throw invalid("Campo " + field + " ausente ou inválido");
146	        return n.asText().trim();
147	    }
148	
149	    private static int integer(JsonNode root, String field) {
150	        JsonNode n = root.get(field);
151	        if (n == null || !n.isIntegralNumber() || !n.canConvertToInt()) {
152	            throw invalid("Campo " + field + " ausente ou inválido");
153	        }
154	        return n.asInt();
155	    }
156	}
