159	import java.math.BigDecimal;
160	import java.time.LocalDate;
161	
162	public final class Domain {
163	    private Domain() {}
164	
165	    public enum RoomType { STANDARD, DELUXE, SUITE }
166	
167	    public enum RatePlan { STANDARD, NON_REFUNDABLE }
168	
169	    public enum Status { PENDING, CONFIRMED, CHECKED_IN, CHECKED_OUT, CANCELLED }
170	
171	    public record Room(int number, RoomType type, int capacity, BigDecimal nightlyRate) {}
172	
173	    public record Reservation(
174	            long id, int roomNumber, String guestName, String guestEmail, String guestCpf,
175	            LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan, int nights,
176	            BigDecimal subtotal, BigDecimal discount, BigDecimal total, Status status,
177	            BigDecimal amountPaid, BigDecimal refund) {
178	
179	        /** Reserva paga: confirmada, com check-in ou com check-out. */
180	        public boolean paid() {
181	            return status == Status.CONFIRMED || status == Status.CHECKED_IN || status == Status.CHECKED_OUT;
182	        }
183	    }
184	
185	    public record Document(
186	            String title, long reservationId, String guestName, String guestCpf, int roomNumber,
187	            RoomType roomType, LocalDate checkIn, LocalDate checkOut, int nights,
188	            BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
189	
190	    public record Message(long id, String channel, String to, String subject, String body, String status) {}
191	
192	    public static class ApiException extends RuntimeException {
193	        public final int status;
194	        public final String code;
195	
196	        public ApiException(int status, String code, String message) {
197	            super(message);
198	            this.status = status;
199	            this.code = code;
200	        }
201	    }
202	}
203	package br.com.marealta.pousada;
204	
205	import br.com.marealta.pousada.Domain.RatePlan;
206	import br.com.marealta.pousada.Domain.Room;
207	
208	import java.math.BigDecimal;
209	import java.math.RoundingMode;
210	import java.text.DecimalFormat;
211	import java.text.DecimalFormatSymbols;
212	import java.time.LocalDate;
213	import java.time.Month;
214	import java.time.temporal.ChronoUnit;
215	import java.util.Locale;
216	
217	public final class Pricing {
218	    private Pricing() {}
219	
220	    private static final BigDecimal HIGH_SEASON = new BigDecimal("1.20");
221	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
222	
223	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
224	
225	    /** Arredondamento para centavos, meio para o par. */
226	    public static BigDecimal money(BigDecimal v) {
227	        return v.setScale(2, RoundingMode.HALF_EVEN);
228	    }
229	
230	    /** Alta temporada: de 15/12 ao fim de fevereiro, e julho inteiro. */
231	    public static boolean highSeason(LocalDate night) {
232	        Month m = night.getMonth();
233	        return m == Month.JANUARY || m == Month.FEBRUARY || m == Month.JULY
234	                || (m == Month.DECEMBER && night.getDayOfMonth() >= 15);
235	    }
236	
237	    public static BigDecimal nightPrice(Room room, LocalDate night) {
238	        BigDecimal rate = room.nightlyRate();
239	        return money(highSeason(night) ? rate.multiply(HIGH_SEASON) : rate);
240	    }
241	
242	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
243	        BigDecimal subtotal = money(BigDecimal.ZERO);
244	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
245	            subtotal = subtotal.add(nightPrice(room, d));
246	        }
247	        BigDecimal discount = plan == RatePlan.NON_REFUNDABLE
248	                ? money(subtotal.multiply(NON_REFUNDABLE_DISCOUNT))
249	                : money(BigDecimal.ZERO);
250	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
251	        return new Quote(nights, subtotal, discount, money(subtotal.subtract(discount)));
252	    }
253	
254	    /** R$ 1.234,56 */
255	    public static String brl(BigDecimal v) {
256	        DecimalFormat f = new DecimalFormat("#,##0.00", DecimalFormatSymbols.getInstance(Locale.of("pt", "BR")));
257	        f.setRoundingMode(RoundingMode.HALF_EVEN);
258	        return "R$ " + f.format(v);
259	    }
260	}

