181	/** Aplica as regras de envio e grava o resultado na lista de mensagens (e-mails ainda não saem de verdade). */
182	public class MailDispatcher {
183	    public static final ZoneId ZONE = ZoneId.of("America/Sao_Paulo");
184	
185	    /** Mensagem a gravar. {@code originalTo} é o destinatário pretendido; {@code copy} marca cópias de arquivo. */
186	    public record NewMessage(String to, String subject, String body, String status,
187	                             String originalTo, boolean copy, Instant createdAt) {}
188	
189	    public interface MailStore {
190	        void save(NewMessage m);
191	
192	        /** Mensagens ENVIADAS (não cópias) cujo destinatário pretendido é {@code address}, no intervalo. */
193	        int countSent(String address, Instant fromInclusive, Instant toExclusive);
194	    }
195	
196	    private final MailConfig config;
197	    private final Clock clock;
198	
199	    public MailDispatcher(MailConfig config, Clock clock) {
200	        this.config = config;
201	        this.clock = clock;
202	    }
203	
204	    public static boolean validAddress(String a) {
205	        if (a == null) return false;
206	        int at = a.indexOf('@');
207	        if (at <= 0 || at != a.lastIndexOf('@')) return false;
208	        for (int i = 0; i < a.length(); i++) if (Character.isWhitespace(a.charAt(i))) return false;
209	        String domain = a.substring(at + 1);
210	        for (int i = 1; i < domain.length() - 1; i++) if (domain.charAt(i) == '.') return true;
211	        return false;
212	    }
213	
214	    public void send(MailStore store, String to, String subject, String body) {
215	        Instant now = clock.instant();
216	        if (blocked(store, to, now)) {
217	            store.save(new NewMessage(to, subject, body, "BLOCKED", to, false, now));
218	            return;
219	        }
220	        List<NewMessage> out = new ArrayList<>();
221	        out.add(new NewMessage(to, subject, body, "SENT", to, false, now));
222	        if (config.archiveCopy().active(config.testMode())) {
223	            out.add(new NewMessage(MailConfig.ARCHIVE_ADDRESS, "[Cópia] " + subject, body, "SENT", to, true, now));
224	        }
225	        for (NewMessage m : out) store.save(config.testMode() ? redirected(m) : m);
226	    }
227	
228	    /** No modo de teste nada sai para o endereço real, nem as cópias de arquivo. */
229	    private static NewMessage redirected(NewMessage m) {
230	        return new NewMessage(MailConfig.TEST_ADDRESS, "[TESTE] " + m.subject(),
231	                "Destinatário original: " + m.to() + "\n" + m.body(),
232	                m.status(), m.originalTo(), m.copy(), m.createdAt());
233	    }
234	
235	    private boolean blocked(MailStore store, String to, Instant now) {
236	        if (!validAddress(to)) return true;
237	        ZonedDateTime local = now.atZone(ZONE);
238	        if (config.quietHours().active(config.testMode()) && inQuietHours(local.getHour())) return true;
239	        if (config.dailyLimit().active(config.testMode())) {
240	            LocalDate day = local.toLocalDate();
241	            Instant from = day.atStartOfDay(ZONE).toInstant();
242	            Instant until = day.plusDays(1).atStartOfDay(ZONE).toInstant();
243	            return store.countSent(to.toLowerCase(Locale.ROOT), from, until) >= config.dailyLimitMax();
244	        }
245	        return false;
246	    }
247	
248	    private boolean inQuietHours(int hour) {
249	        int s = config.quietStartHour(), e = config.quietEndHour();
250	        if (s == e) return false;
251	        return s < e ? hour >= s && hour < e : hour >= s || hour < e;
252	    }
253	}
