  2	
  3	import br.com.marealta.pousada.Domain.*;
  4	
  5	import java.math.BigDecimal;
  6	import java.sql.*;
  7	import java.time.Instant;
  8	import java.time.LocalDate;
  9	import java.util.ArrayList;
 10	import java.util.List;
 11	import java.util.Optional;
 12	
 13	/** Acesso ao banco dentro de uma transação. */
 14	public class Repo implements MailDispatcher.MailStore {
 15	    private final Connection c;
 16	
 17	    Repo(Connection c) {
 18	        this.c = c;
 19	    }
 20	
 21	    private static RuntimeException wrap(SQLException e) {
 22	        return new IllegalStateException(e);
 23	    }
 24	
 25	    void createSchema() {
 26	        try (Statement st = c.createStatement()) {
 27	            st.execute("""
 28	                    CREATE TABLE IF NOT EXISTS rooms (
 29	                      number INT PRIMARY KEY,
 30	                      type TEXT NOT NULL,
 31	                      capacity INT NOT NULL,
 32	                      nightly_rate NUMERIC(12,2) NOT NULL)""");
 33	            st.execute("""
 34	                    CREATE TABLE IF NOT EXISTS reservations (
 35	                      id BIGSERIAL PRIMARY KEY,
 36	                      room_number INT NOT NULL REFERENCES rooms(number),
 37	                      guest_name TEXT NOT NULL,
 38	                      guest_email TEXT NOT NULL,
 39	                      guest_cpf TEXT NOT NULL,
 40	                      check_in DATE NOT NULL,
 41	                      check_out DATE NOT NULL,
 42	                      guests INT NOT NULL,
 43	                      rate_plan TEXT NOT NULL,
 44	                      nights INT NOT NULL,
 45	                      subtotal NUMERIC(12,2) NOT NULL,
 46	                      discount NUMERIC(12,2) NOT NULL,
 47	                      total NUMERIC(12,2) NOT NULL,
 48	                      status TEXT NOT NULL,
 49	                      amount_paid NUMERIC(12,2) NOT NULL,
 50	                      refund NUMERIC(12,2))""");
 51	            st.execute("""
 52	                    CREATE TABLE IF NOT EXISTS messages (
 53	                      id BIGSERIAL PRIMARY KEY,
 54	                      channel TEXT NOT NULL,
 55	                      to_addr TEXT NOT NULL,
 56	                      subject TEXT NOT NULL,
 57	                      body TEXT NOT NULL,
 58	                      status TEXT NOT NULL,
 59	                      original_to TEXT NOT NULL,
 60	                      copy BOOLEAN NOT NULL,
 61	                      created_at TIMESTAMPTZ NOT NULL)""");
 62	            st.execute("""
 63	                    INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
 64	                      (101, 'STANDARD', 2, 249.90), (102, 'STANDARD', 2, 249.90),
 65	                      (201, 'DELUXE', 3, 389.90), (202, 'DELUXE', 3, 389.90),
 66	                      (301, 'SUITE', 4, 579.90)
 67	                    ON CONFLICT (number) DO NOTHING""");
 68	        } catch (SQLException e) {
 69	            throw wrap(e);
 70	        }
 71	    }
 72	
 73	    // ---- quartos
 74	
 75	    private static Room room(ResultSet rs) throws SQLException {
 76	        return new Room(rs.getInt("number"), RoomType.valueOf(rs.getString("type")),
 77	                rs.getInt("capacity"), rs.getBigDecimal("nightly_rate"));
 78	    }
 79	
 80	    public List<Room> rooms() {
 81	        try (Statement st = c.createStatement(); ResultSet rs = st.executeQuery("SELECT * FROM rooms ORDER BY number")) {
 82	            List<Room> out = new ArrayList<>();
 83	            while (rs.next()) out.add(room(rs));
 84	            return out;
 85	        } catch (SQLException e) {
 86	            throw wrap(e);
 87	        }
 88	    }
 89	
 90	    public Optional<Room> room(int number) {
 91	        try (PreparedStatement ps = c.prepareStatement("SELECT * FROM rooms WHERE number = ?")) {
 92	            ps.setInt(1, number);
 93	            try (ResultSet rs = ps.executeQuery()) {
 94	                return rs.next() ? Optional.of(room(rs)) : Optional.empty();
 95	            }
 96	        } catch (SQLException e) {
 97	            throw wrap(e);
 98	        }
 99	    }
100	
101	    // ---- reservas
102	
103	    private static Reservation reservation(ResultSet rs) throws SQLException {
104	        return new Reservation(rs.getLong("id"), rs.getInt("room_number"), rs.getString("guest_name"),
105	                rs.getString("guest_email"), rs.getString("guest_cpf"),
106	                rs.getObject("check_in", LocalDate.class), rs.getObject("check_out", LocalDate.class),
107	                rs.getInt("guests"), RatePlan.valueOf(rs.getString("rate_plan")), rs.getInt("nights"),
108	                rs.getBigDecimal("subtotal"), rs.getBigDecimal("discount"), rs.getBigDecimal("total"),
109	                Status.valueOf(rs.getString("status")), rs.getBigDecimal("amount_paid"), rs.getBigDecimal("refund"));
110	    }
111	
112	    public Optional<Reservation> reservation(long id) {
113	        try (PreparedStatement ps = c.prepareStatement("SELECT * FROM reservations WHERE id = ?")) {
114	            ps.setLong(1, id);
115	            try (ResultSet rs = ps.executeQuery()) {
116	                return rs.next() ? Optional.of(reservation(rs)) : Optional.empty();
117	            }
118	        } catch (SQLException e) {
119	            throw wrap(e);
120	        }
121	    }
122	
123	    public boolean hasOverlap(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
124	        try (PreparedStatement ps = c.prepareStatement("""
125	                SELECT 1 FROM reservations
126	                WHERE room_number = ? AND status <> 'CANCELLED' AND check_in < ? AND check_out > ?
127	                LIMIT 1""")) {
128	            ps.setInt(1, roomNumber);
129	            ps.setObject(2, checkOut);
130	            ps.setObject(3, checkIn);
131	            try (ResultSet rs = ps.executeQuery()) {
132	                return rs.next();
133	            }
134	        } catch (SQLException e) {
135	            throw wrap(e);
136	        }
137	    }
138	
139	    public Reservation insert(Reservation r) {
140	        try (PreparedStatement ps = c.prepareStatement("""
141	                INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
142	                  guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund)
143	                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id""")) {
144	            ps.setInt(1, r.roomNumber());
145	            ps.setString(2, r.guestName());
146	            ps.setString(3, r.guestEmail());
147	            ps.setString(4, r.guestCpf());
148	            ps.setObject(5, r.checkIn());
149	            ps.setObject(6, r.checkOut());
150	            ps.setInt(7, r.guests());
151	            ps.setString(8, r.ratePlan().name());
152	            ps.setInt(9, r.nights());
153	            ps.setBigDecimal(10, r.subtotal());
154	            ps.setBigDecimal(11, r.discount());
155	            ps.setBigDecimal(12, r.total());
156	            ps.setString(13, r.status().name());
157	            ps.setBigDecimal(14, r.amountPaid());
158	            ps.setBigDecimal(15, r.refund());
159	            try (ResultSet rs = ps.executeQuery()) {
160	                rs.next();
161	                return reservation(rs.getLong(1)).orElseThrow();
162	            }
163	        } catch (SQLException e) {
164	            throw wrap(e);
165	        }
166	    }
167	
168	    public Reservation updateState(long id, Status status, BigDecimal amountPaid, BigDecimal refund) {
169	        try (PreparedStatement ps = c.prepareStatement(
170	                "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
171	            ps.setString(1, status.name());
172	            ps.setBigDecimal(2, amountPaid);
173	            ps.setBigDecimal(3, refund);
174	            ps.setLong(4, id);
175	            ps.executeUpdate();
176	            return reservation(id).orElseThrow();
177	        } catch (SQLException e) {
178	            throw wrap(e);
179	        }
180	    }
181	
182	    /** Reservas pagas que ocupam um quarto na noite indicada, por número do quarto. */
183	    public List<Reservation> occupying(LocalDate night) {
184	        return query("""
185	                SELECT * FROM reservations
186	                WHERE status IN ('CONFIRMED','CHECKED_IN','CHECKED_OUT') AND check_in <= ? AND check_out > ?
187	                ORDER BY room_number, id""", night, night);
188	    }
189	
190	    /** Reservas que começam no período e ficaram com dinheiro (pago menos devolvido). */
191	    public List<Reservation> revenueStartingBetween(LocalDate fromInclusive, LocalDate toExclusive) {
192	        return query("""
193	                SELECT * FROM reservations
194	                WHERE check_in >= ? AND check_in < ? AND amount_paid - COALESCE(refund, 0) > 0
195	                ORDER BY check_in, id""", fromInclusive, toExclusive);
196	    }
197	
198	    private List<Reservation> query(String sql, Object... params) {
199	        try (PreparedStatement ps = c.prepareStatement(sql)) {
200	            for (int i = 0; i < params.length; i++) ps.setObject(i + 1, params[i]);
201	            try (ResultSet rs = ps.executeQuery()) {
202	                List<Reservation> out = new ArrayList<>();
203	                while (rs.next()) out.add(reservation(rs));
204	                return out;
205	            }
206	        } catch (SQLException e) {
207	            throw wrap(e);
208	        }
209	    }
210	
211	    // ---- mensagens
212	
213	    @Override
214	    public void save(MailDispatcher.NewMessage m) {
215	        try (PreparedStatement ps = c.prepareStatement("""
216	                INSERT INTO messages (channel, to_addr, subject, body, status, original_to, copy, created_at)
217	                VALUES ('EMAIL',?,?,?,?,?,?,?)""")) {
218	            ps.setString(1, m.to());
219	            ps.setString(2, m.subject());
220	            ps.setString(3, m.body());
221	            ps.setString(4, m.status());
222	            ps.setString(5, m.originalTo());
223	            ps.setBoolean(6, m.copy());
224	            ps.setObject(7, m.createdAt().atOffset(java.time.ZoneOffset.UTC));
225	            ps.executeUpdate();
226	        } catch (SQLException e) {
227	            throw wrap(e);
228	        }
229	    }
230	
231	    @Override
232	    public int countSent(String address, Instant from, Instant to) {
233	        try (PreparedStatement ps = c.prepareStatement("""
234	                SELECT count(*) FROM messages
235	                WHERE status = 'SENT' AND NOT copy AND lower(original_to) = ?
236	                  AND created_at >= ? AND created_at < ?""")) {
237	            ps.setString(1, address);
238	            ps.setObject(2, from.atOffset(java.time.ZoneOffset.UTC));
239	            ps.setObject(3, to.atOffset(java.time.ZoneOffset.UTC));
240	            try (ResultSet rs = ps.executeQuery()) {
241	                rs.next();
242	                return rs.getInt(1);
243	            }
244	        } catch (SQLException e) {
245	            throw wrap(e);
246	        }
247	    }
248	
249	    public List<Message> messages() {
250	        try (Statement st = c.createStatement();
251	             ResultSet rs = st.executeQuery("SELECT * FROM messages ORDER BY id")) {
252	            List<Message> out = new ArrayList<>();
253	            while (rs.next()) {
254	                out.add(new Message(rs.getLong("id"), rs.getString("channel"), rs.getString("to_addr"),
255	                        rs.getString("subject"), rs.getString("body"), rs.getString("status")));
256	            }
257	            return out;
258	        } catch (SQLException e) {
259	            throw wrap(e);
260	        }
261	    }
262	}
263	package br.com.marealta.pousada;
264	
265	import com.zaxxer.hikari.HikariConfig;
266	import com.zaxxer.hikari.HikariDataSource;
267	
268	import java.sql.Connection;
269	import java.sql.SQLException;
270	import java.sql.Statement;
271	import java.util.function.Function;
272	
273	public class Db implements AutoCloseable {
274	    private static final long WRITE_LOCK = 7001L;
275	
276	    private final HikariDataSource ds;
277	
278	    public Db(String url, String user, String password) {
279	        HikariConfig c = new HikariConfig();
280	        c.setJdbcUrl(url);
281	        if (user != null) c.setUsername(user);
282	        if (password != null) c.setPassword(password);
283	        c.setMaximumPoolSize(10);
284	        c.setInitializationFailTimeout(-1);
285	        this.ds = new HikariDataSource(c);
286	    }
287	
288	    /** Cria o que falta no banco; tenta por um tempo, caso o banco ainda esteja subindo. */
289	    public void init() {
290	        RuntimeException last = null;
291	        for (int i = 0; i < 30; i++) {
292	            try {
293	                write(repo -> { repo.createSchema(); return null; });
294	                return;
295	            } catch (RuntimeException e) {
296	                last = e;
297	                try { Thread.sleep(1000); } catch (InterruptedException ie) { Thread.currentThread().interrupt(); break; }
298	            }
299	        }
300	        throw new IllegalStateException("Não foi possível preparar o banco", last);
301	    }
302	
303	    /** Transação de escrita, serializada entre todas as instâncias (evita reservas sobrepostas). */
304	    public <T> T write(Function<Repo, T> work) {
305	        return run(true, work);
306	    }
307	
308	    public <T> T read(Function<Repo, T> work) {
309	        return run(false, work);
310	    }
311	
312	    private <T> T run(boolean lock, Function<Repo, T> work) {
313	        try (Connection conn = ds.getConnection()) {
314	            conn.setAutoCommit(false);
315	            try {
316	                if (lock) {
317	                    try (Statement st = conn.createStatement()) {
318	                        st.execute("SELECT pg_advisory_xact_lock(" + WRITE_LOCK + ")");
319	                    }
320	                }
321	                T result = work.apply(new Repo(conn));
322	                conn.commit();
323	                return result;
324	            } catch (Throwable t) {
325	                conn.rollback();
326	                throw t;
327	            }
328	        } catch (SQLException e) {
329	            throw new IllegalStateException(e);
330	        }
331	    }
332	
333	    @Override
334	    public void close() {
335	        ds.close();
336	    }
337	}

