265	import com.zaxxer.hikari.HikariConfig;
266	import com.zaxxer.hikari.HikariDataSource;
267	
268	import java.sql.Connection;
269	import java.sql.SQLException;
270	import java.sql.Statement;
271	import java.util.function.Function;
272	
273	public class Db implements AutoCloseable {
274	    private static final long WRITE_LOCK = 7001L;
275	
276	    private final HikariDataSource ds;
277	
278	    public Db(String url, String user, String password) {
279	        HikariConfig c = new HikariConfig();
280	        c.setJdbcUrl(url);
281	        if (user != null) c.setUsername(user);
282	        if (password != null) c.setPassword(password);
283	        c.setMaximumPoolSize(10);
284	        c.setInitializationFailTimeout(-1);
285	        this.ds = new HikariDataSource(c);
286	    }
287	
288	    /** Cria o que falta no banco; tenta por um tempo, caso o banco ainda esteja subindo. */
289	    public void init() {
290	        RuntimeException last = null;
291	        for (int i = 0; i < 30; i++) {
292	            try {
293	                write(repo -> { repo.createSchema(); return null; });
294	                return;
295	            } catch (RuntimeException e) {
296	                last = e;
297	                try { Thread.sleep(1000); } catch (InterruptedException ie) { Thread.currentThread().interrupt(); break; }
298	            }
299	        }
300	        throw new IllegalStateException("Não foi possível preparar o banco", last);
301	    }
302	
303	    /** Transação de escrita, serializada entre todas as instâncias (evita reservas sobrepostas). */
304	    public <T> T write(Function<Repo, T> work) {
305	        return run(true, work);
306	    }
307	
308	    public <T> T read(Function<Repo, T> work) {
309	        return run(false, work);
310	    }
311	
312	    private <T> T run(boolean lock, Function<Repo, T> work) {
313	        try (Connection conn = ds.getConnection()) {
314	            conn.setAutoCommit(false);
315	            try {
316	                if (lock) {
317	                    try (Statement st = conn.createStatement()) {
318	                        st.execute("SELECT pg_advisory_xact_lock(" + WRITE_LOCK + ")");
319	                    }
320	                }
321	                T result = work.apply(new Repo(conn));
322	                conn.commit();
323	                return result;
324	            } catch (Throwable t) {
325	                conn.rollback();
326	                throw t;
327	            }
328	        } catch (SQLException e) {
329	            throw new IllegalStateException(e);
330	        }
331	    }
332	
333	    @Override
334	    public void close() {
335	        ds.close();
336	    }
337	}

