238	    static Resp call(String method, String path, String body) throws Exception {
239	        var b = HttpRequest.newBuilder(URI.create(baseUrl + path));
240	        b.header("Content-Type", "application/json");
241	        b.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body));
242	        var r = HTTP.send(b.build(), HttpResponse.BodyHandlers.ofString());
243	        return new Resp(r.statusCode(), r.body(), r.headers().firstValue("content-type").orElse(""));
244	    }
