325	    void cancellationsAndRefunds() throws Exception {
326	        // não reembolsável confirmada: sem devolução, continua no financeiro
327	        long a = call("POST", "/reservations", req(301, "a@x.com", "2028-05-01", "2028-05-03", 4, "NON_REFUNDABLE")).json().get("id").asLong();
328	        JsonNode ra = call("GET", "/reservations/" + a, null).json();
329	        assertEquals(1159.80, ra.get("subtotal").asDouble());
330	        assertEquals(173.97, ra.get("discount").asDouble());
331	        assertEquals(985.83, ra.get("total").asDouble());
332	        call("POST", "/reservations/" + a + "/confirmation", null);
333	        JsonNode ca = call("POST", "/reservations/" + a + "/cancellation", null).json();
334	        assertEquals("CANCELLED", ca.get("status").asText());
335	        assertEquals(0.0, ca.get("refund").asDouble());
336	        // a data liberou-se
337	        long b = call("POST", "/reservations", req(301, "b@x.com", "2028-05-01", "2028-05-03", 1, "STANDARD")).json().get("id").asLong();
338	        // padrão confirmada: devolve tudo
339	        call("POST", "/reservations/" + b + "/confirmation", null);
340	        JsonNode cb = call("POST", "/reservations/" + b + "/cancellation", null).json();
341	        assertEquals(1159.80, cb.get("refund").asDouble());
342	        // pendente: nada a devolver
343	        long c = call("POST", "/reservations", req(301, "c@x.com", "2028-05-01", "2028-05-03", 1, "STANDARD")).json().get("id").asLong();
344	        assertEquals(0.0, call("POST", "/reservations/" + c + "/cancellation", null).json().get("refund").asDouble());
345	        assertEquals(409, call("POST", "/reservations/" + c + "/cancellation", null).status());
346	
347	        String rev = call("GET", "/reports/revenue?month=2028-05", null).body();
348	        assertTrue(rev.contains(a + ",301,2028-05-01,2028-05-03,CANCELLED,985.83\n"), rev);
349	        assertFalse(rev.contains("\n" + b + ","), rev);
350	        assertTrue(rev.endsWith("total,985.83\n"), rev);
351	    }
