376	        Resp cap = call("POST", "/reservations", req(101, "a@b.com", "2027-03-10", "2027-03-11", 3, "STANDARD"));
377	        assertEquals(422, cap.status());
378	        assertEquals("CAPACITY_EXCEEDED", cap.json().get("error").asText());
379	        assertEquals("RESERVATION_NOT_FOUND", call("GET", "/reservations/99999", null).json().get("error").asText());
380	        assertEquals(404, call("POST", "/reservations/abc/check-in", null).status());
381	        assertEquals(400, call("GET", "/reports/occupancy?date=2027-3-1", null).status());
382	        assertEquals(400, call("GET", "/reports/occupancy", null).status());
383	        assertEquals(400, call("GET", "/reports/revenue?month=2027-13", null).status());
384	    }
